using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Options;using TradingSystem.Application.Execution;using TradingSystem.Application.Healing;using TradingSystem.Application.Orders;using TradingSystem.Application.Positions;using TradingSystem.Application.Strategies;using TradingSystem.Binance.Startup;
namespace StrategyService.Bots.Bot8015;public static class DependencyInjection{public static IServiceCollection AddBot8015(this IServiceCollection s, IConfiguration c){s.AddOptions<Bot8015Options>().Bind(c.GetSection(Bot8015Options.SectionName)).ValidateOnStart();s.AddSingleton<IValidateOptions<Bot8015Options>, Bot8015OptionsValidator>();s.AddSingleton<IBinanceTradingConfiguration>(sp => sp.GetRequiredService<IOptions<Bot8015Options>>().Value);s.AddSingleton<ITradingStrategy, Bot8015Strategy>();s.AddSingleton<IBotTradeExecutor, Bot8015TradeExecutor>();s.AddSingleton<IBotActivePositionProvider, Bot8015ActivePositionProvider>();s.AddSingleton<IBotOrderEventHandler, Bot8015OrderEventHandler>();s.AddSingleton<IBotHealingService, Bot8015HealingService>();s.AddSingleton<Bot8015Stop3OrderService>();s.AddSingleton<Bot8015PositionEvents>();s.AddSingleton<Bot8015TrailingPriceCache>();s.AddHostedService<Bot8015KlineSubscriber>();s.AddHostedService<Bot8015TrailingWorker>();return s;}}
